'<div class="product-related"><a href="'+url('','#software')+'">'+esc(c.related)+' ↗</a><a href="mailto:hello@auxtho.com">'+esc(c.contactLink)+' ↗</a></div></section>'+(p.id==='auxtho'?film():'')+contact();
