function bindTabs(){
const tabs=[...document.querySelectorAll('[role=tab]')];
const select=i=>{const t=c.tabs[i];tabs.forEach((b,n)=>{b.setAttribute('aria-selected',String(n===i));b.tabIndex=n===i?0:-1;});document.querySelector('#evidence-panel').setAttribute('aria-labelledby','tab-'+i);const img=document.querySelector('.evidence-screen img');img.src=asset(t.image);img.alt=displayCopy(t.title);document.querySelector('.evidence-copy h3').textContent=displayCopy(t.title);document.querySelector('.tab-body').textContent=displayCopy(t.body);document.querySelector('.proof-status').textContent=displayCopy(t.note);};
tabs.forEach((b,i)=>{b.addEventListener('click',()=>select(i));b.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowLeft')n=(i-1+tabs.length)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();select(n);tabs[n].focus();}});});
}
function bindImageDialog(){
const dialog=document.querySelector('.image-dialog');
const nativeLabel=lang==='ko'?'원본 배율':'Native size',fitLabel=lang==='ko'?'화면에 맞춤':'Fit to screen';
dialog.querySelector('.dialog-close').insertAdjacentHTML('beforebegin','<button class="dialog-zoom" type="button" aria-pressed="false">'+nativeLabel+'</button>');
const zoom=dialog.querySelector('.dialog-zoom');
zoom.addEventListener('click',()=>{const native=dialog.classList.toggle('native-size');zoom.setAttribute('aria-pressed',String(native));zoom.textContent=native?fitLabel:nativeLabel;dialog.scrollTo({left:0,top:0});});
document.querySelector('#main').addEventListener('click',e=>{const button=e.target.closest('[data-enlarge],.evidence-screen');if(!button)return;const src=button.querySelector('img');if(!src)return;dialog.classList.remove('native-size');zoom.setAttribute('aria-pressed','false');zoom.textContent=nativeLabel;dialog.querySelector('img').src=src.src;dialog.querySelector('img').alt=src.alt;dialog.querySelector('p').textContent=src.alt;dialog.showModal();dialog.scrollTo({left:0,top:0});});
dialog.querySelector('.dialog-close').textContent=c.close+' ×';dialog.querySelector('.dialog-close').setAttribute('aria-label',lang==='ko'?'이미지 닫기':'Close image');
dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});
}
if(current)renderDetail(current);else renderHome();
